-- ----------------------------
-- Table structure for dorm_alarm_device
-- ----------------------------
DROP TABLE IF EXISTS `dorm_alarm_device`;
CREATE TABLE `dorm_alarm_device`  (
  `device_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键，设备ID',
  `dorm_id` bigint(20) NOT NULL COMMENT '所属宿舍/房间ID',
  `device_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设备名称',
  `device_type` tinyint(4) NOT NULL COMMENT '设备类型，\'0\'为烟雾报警器',
  `location` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '安装位置',
  `status` tinyint(4) NULL DEFAULT 0 COMMENT '设备状态（0离线，1在线）',
  `last_online_time` datetime NULL DEFAULT NULL COMMENT '最后一次在线时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`device_id`) USING BTREE,
  INDEX `idx_dorm_id`(`dorm_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '报警设备表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of dorm_alarm_device
-- ----------------------------

-- ----------------------------
-- Table structure for dorm_alarm_log
-- ----------------------------
DROP TABLE IF EXISTS `dorm_alarm_log`;
CREATE TABLE `dorm_alarm_log`  (
  `alarm_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键，告警ID',
  `device_id` bigint(20) NOT NULL COMMENT '对应报警设备ID',
  `dorm_id` bigint(20) NOT NULL COMMENT '房间ID',
  `smoke_value` double NOT NULL COMMENT '告警时烟雾值',
  `alarm_level` tinyint(4) NULL DEFAULT 1 COMMENT '告警等级（1一般，2严重等）',
  `alarm_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '告警时间',
  `handled` tinyint(4) NULL DEFAULT 0 COMMENT '是否处理（0未处理，1已处理）',
  `handled_time` datetime NULL DEFAULT NULL COMMENT '处理时间',
  `handler` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '处理人',
  `remarks` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`alarm_id`) USING BTREE,
  INDEX `idx_device_id`(`device_id` ASC) USING BTREE,
  CONSTRAINT `fk_alarm_device` FOREIGN KEY (`device_id`) REFERENCES `dorm_alarm_device` (`device_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '报警记录表' ROW_FORMAT = Dynamic;

