-- ----------------------------
-- Procedure structure for CleanExpiredDispatchLocks
-- ----------------------------
DROP PROCEDURE IF EXISTS `CleanExpiredDispatchLocks`;
delimiter ;;
CREATE PROCEDURE `CleanExpiredDispatchLocks`()
BEGIN
    DELETE FROM `dorm_repair_dispatch_lock` 
    WHERE `expire_time` < NOW();
END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
