INSERT INTO `dorm_notice` VALUES (36, '禁止大功率电器通告', 'http://img.campus.com/electrical-warning.jpg', '0', '<p>重申宿舍禁止使用电炉、电锅等大功率电器。</p>', '0', 'admin', '2025-05-20 08:45:00', NULL, '2025-06-15 16:34:43', '安全警示', '0', 0);
